import pLimit from 'p-limit';
import Queue from 'yocto-queue';
const limit=pLimit(2); const value: Promise<number>=limit((n:number)=>n+1,7);

import pLimit from 'p-limit';
import Queue from 'yocto-queue';
const limit=pLimit(2); const value: Promise<string>=limit(async (n:number)=>String(n),7);

import pLimit from 'p-limit';
import Queue from 'yocto-queue';
const value: Promise<number>=pLimit(2);

import pLimit from 'p-limit';
import Queue from 'yocto-queue';
const limit=pLimit(2); limit((n:number)=>n+1,'wrong');

import pLimit from 'p-limit';
import Queue from 'yocto-queue';
const limit=pLimit(2); limit.activeCount=3;

import pLimit from 'p-limit';
import Queue from 'yocto-queue';
const limit=pLimit(2); limit.pendingCount=3;

import pLimit from 'p-limit';
import Queue from 'yocto-queue';
const limit=pLimit(2); const value: Promise<void>=limit.clearQueue();

import pLimit from 'p-limit';
import Queue from 'yocto-queue';
const limit=pLimit('2');

import pLimit from 'p-limit';
import Queue from 'yocto-queue';
const limit=pLimit(0);

import pLimit from 'p-limit';
import Queue from 'yocto-queue';
const limit=pLimit(1.5);

import pLimit from 'p-limit';
import Queue from 'yocto-queue';
const limit=pLimit(Infinity);

import pLimit from 'p-limit';
import Queue from 'yocto-queue';
const queue=new Queue<number>(); const value: number=queue.dequeue();

import pLimit from 'p-limit';
import Queue from 'yocto-queue';
const queue=new Queue<number|undefined>(); queue.enqueue(undefined); const value:number|undefined=queue.dequeue();

import pLimit from 'p-limit';
import Queue from 'yocto-queue';
const queue=new Queue<number>(); queue.enqueue('wrong');

import pLimit from 'p-limit';
import Queue from 'yocto-queue';
const queue=new Queue<number>(); queue.enqueue(7); const values:number[]=[...queue];

import pLimit from 'p-limit';
import Queue from 'yocto-queue';
const limit=pLimit(2); limit.map([1,2],(n:number)=>n);
